    "aka": "novel short story storytelling narrative",
    "tag": "Narrative prose about imagined characters and events",
    "desc": "Composition of narrative prose about imagined characters and events, in forms ranging from the short story and novella to the novel. Its recognized elements include point of view, characterization, plot, setting, dialogue and theme, and it is divided into genres such as literary, historical, crime, romance, science fiction and fantasy. The modern novel developed in Europe between the seventeenth and eighteenth centuries, with Cervantes's Don Quixote often cited as an early landmark. Composition is iterative, moving through drafting, revision and editing, and works reach readers through publishers, magazines and self-publication. Writers who keep at it care more about the third draft than the first, and the habit of finishing something, badly, on a schedule matters more than waiting to feel ready.",
    "start": "Write a 1,000-word story in which one character wants something and is stopped."
