    "aka": "essay memoir reporting narrative nonfiction literary non-fiction",
    "tag": "Factual prose, from essay and memoir to reporting",
    "desc": "Nonfiction writing presents factual material in prose and includes the essay, memoir, biography and journalism. Literary or narrative nonfiction, sometimes called creative nonfiction, applies techniques associated with fiction, such as scene, characterization and structure, to verifiable subjects. Michel de Montaigne's Essais (1580) established the modern essay, and the New Journalism of the 1960s, associated with Tom Wolfe, Gay Talese and Joan Didion, popularized the narrative approach. Professional standards center on research, sourcing, verification and attribution. Anyone who writes nonfiction has to decide what is worth saying out loud, and that selection is the whole discipline: it favors people with strong opinions and a tolerance for verifying things.",
    "start": "Interview someone about a job they have done for years and write it up in 800 words."
