    "aka": "foley sound effects foley artist",
    "tag": "Live performance of sound effects for film",
    "desc": "The reproduction of everyday sound effects added to film, video and games in post-production, performed live to picture by a Foley artist on a specially equipped stage. Typical sounds include footsteps, cloth movement and the handling of props, produced with surfaces and objects chosen for their sound. The technique is named after Jack Foley, a sound-effects pioneer at Universal Studios who developed it around 1929, at the start of the sound-film era. Foley recordings are layered with dialogue, music and other effects in the final mix.",
    "start": "Record footsteps on three different surfaces to match a short clip."
