    "desc": "Form of vocal percussion in which a performer imitates drum machines, drums and other sounds with the mouth, lips, tongue and voice. It emerged in the early 1980s in New York hip-hop culture, with early figures such as Doug E. Fresh, and developed into a solo art with techniques including inward snares, lip rolls and simultaneous humming. Competitions such as the Beatbox Battle World Championship have been held since 2005, and loop stations allow performers to layer sounds live.",
