    "desc": "A disc jockey plays and blends recorded music for an audience, whether on radio, in a nightclub or at a live event. Club DJing developed from the discotheque of the 1960s and 1970s, in which the seamless mixing of records was pioneered by Francis Grasso, while hip-hop DJs such as Kool Herc and Grandmaster Flash created breakbeat techniques and turntablism. Core skills are beatmatching, phrasing, equalization, cueing and track selection, using turntables, CD players or digital controllers with software.",
