    "desc": "A performance practice in which a musician writes and edits code in real time to generate sound, with the process typically projected for the audience. It grew from academic computer music and the TOPLAP movement, founded in 2004, and uses languages and environments such as TidalCycles, Sonic Pi and SuperCollider. Algorave, a term coined around 2011 by Nick Collins and Alex McLean, denotes club and festival events built around live-coded electronic music and visuals. The practice treats the source code as both instrument and score.",
