    "aka": "professional wrestling martial performance stage fighting fight choreography",
    "tag": "Choreographed combat for stage, screen and wrestling",
    "desc": "Stage combat is the choreography and performance of simulated fighting, using sword work, unarmed technique and falls designed for safety and dramatic effect on stage or screen; professional wrestling extends the practice into a full athletic performance genre combining scripted outcomes with live combat choreography. Organizations such as the Society of American Fight Directors, founded in 1977, certify stage combat instructors and techniques. Wrestling promotions including the World Wrestling Federation, renamed WWE in 2002, developed the form into a globally broadcast entertainment industry. Both fields depend on trust, timing and rehearsed contact to protect performers. Stage combat is choreography with real risk attached, and it needs people who can be aggressive on stage and extremely careful with each other off it.",
