    "desc": "Specification of the rules, mechanics, goals, progression and player experience of a digital game, distinct from programming, art and audio production though closely coordinated with them. Designers prototype and iterate using engines such as Unity and Unreal Engine, or the free Godot engine, and test extensively with players to refine feedback and balance. Influential design writing includes Chris Crawford's The Art of Computer Game Design (1984) and Jesse Schell's The Art of Game Design (2008). The discipline draws on systems thinking, psychology and, in narrative-driven games, writing.",
