    "tag": "Design of rules for board, card and role-playing games",
    "desc": "Creation of rules, components and systems for board games, card games and tabletop role-playing games, played without requiring digital hardware. Modern hobby board game design was reshaped by German-style, or Eurogame, design from the 1990s, exemplified by Klaus Teuber's The Settlers of Catan (1995), emphasizing resource management over direct conflict. Tabletop role-playing games originate with Dungeons & Dragons, created by Gary Gygax and Dave Arneson and published in 1974. Design proceeds through iterative prototyping and playtesting to balance mechanics and player interaction.",
