    "aka": "torch work, lampworking, scientific and bead glasswork",
    "tag": "Melting and shaping glass rod or tube over a small torch flame, typically alone at a bench",
    "desc": "Flameworking melts glass rod or tubing locally with a bench torch rather than pulling shapes from a furnace of molten glass, letting a single artist work in full detail at close range on beads, marbles, small sculpture, scientific glassware and borosilicate pipes without the furnace crew Glassblowing requires. The technique takes its older name, lampworking, from the oil lamps early practitioners used before gas torches, and Venetian glassmakers on the island of Murano refined bead and figurine lampworking into a specialized trade from the sixteenth century onward, distinct from the island's furnace-based blown glass. Because the glass is heated and cooled only where the flame touches it rather than the whole piece staying uniformly molten, flameworkers build up a piece through repeated, localized reheating rather than a single continuous working window, giving them far more control at small scale but making anything beyond tabletop size impractical, the opposite trade-off from furnace glassblowing.",
    "start": "Watch a lampworker at the bench in a video and note how the glass is heated, turned and shaped; then look up studios that offer introductory lampworking."
