    "aka": "synchronized swimming synchro water ballet nado sincronizado natacion artistica pool routine",
    "tag": "Choreographed team and duet routines performed in the water to music",
    "desc": "Water sport and performing art, formerly called synchronized swimming, in which swimmers perform choreographed routines to music in solos, duets and teams, combining sculling, leg movements, lifts and figures with precise synchronization. Competitions score technical elements and artistic impression. Because performers spend much of a routine upside down and holding their breath, training builds breath control and core strength. It has been an Olympic discipline since 1984, and World Aquatics renamed the sport artistic swimming in 2017.",
    "start": "Look up beginner artistic swimming or masters groups near you; sculling and the eggbeater kick are best learned with a coach, never alone in the water."
