    "aka": "ribbon hoop ball clubs rope gimnasia ritmica gymnast apparatus routine",
    "tag": "Floor routines to music with hoop, ball, clubs and ribbon",
    "desc": "Sport and performing art in which gymnasts perform choreographed routines to music on a floor mat with hand apparatus: hoop, ball, clubs and ribbon (and rope at some levels). Routines combine dance, flexibility, balance, and throws and catches, and are scored for difficulty, execution and artistry. Individual and group events exist, and it has been an Olympic sport since 1984, with group events added in 1996. Rhythmic gymnastics joins gymnastics to dance and music, and the athletes are the sort who like a rule set that has to be felt as well as counted.",
    "start": "Practice ribbon snakes and spirals with a scarf tied to a stick, then look up beginner rhythmic gymnastics classes near you."
