    "desc": "Persian ritual theater from Iran commemorating the martyrdom of Imam Hussein at Karbala in 680 CE, performed especially during the month of Muharram. Performers sing and recite in a heightened, chanted style, with roles marked by costume color, and the audience is emotionally involved, often weeping. It grew from mourning rites and storytelling into a full theatrical tradition, and is performed in dedicated spaces called tekyeh.",
