    "aka": "framebuilding frame builder custom bike bicycle building custom motorcycle cafe racer bobber chopper",
    "tag": "One-off machines, built by hand",
    "desc": "Building or heavily reworking bicycles and motorcycles as one-off machines. Framebuilders cut, miter and join steel or other tubing by brazing or welding, and custom motorcycle builders fabricate, modify and paint bikes into styles such as café racers, bobbers and choppers. Fit, geometry, function and looks are all design decisions. Building a bicycle or motorcycle frame means the person who welds it has to be right about geometry, because a frame cannot be adjusted afterwards the way a car can.",
    "start": "Name every part of a bicycle you already have, then clean and adjust its brakes and gears, learning what each part does."
