    "tag": "Fabricating the hard and handheld parts of a costume",
    "desc": "Fabricating the hard and handheld parts of costumes and sets: armor, weapons, helmets and set props in foam, thermoplastics, resin, leather, metal and 3D prints. Makers pattern, carve, seal, cast and paint lightweight pieces that look like metal or stone, for cosplay, theater, film and reenactment. Prop and armor making is a convincing lie at a scale somebody else will be inside of, so the work is driven entirely by what will be seen from the audience.",
    "start": "Make a prop sword or helmet from cardboard and tape, working from a pattern you draw yourself."
