    "tag": "Building objects that hide their own solution",
    "desc": "Designing and building physical puzzles: interlocking burr puzzles, sliding-piece boxes and secret-mechanism puzzle boxes that open only through a hidden sequence of moves. Makers work in wood, metal or 3D prints and tune tolerances for a satisfying solve, in traditions that include Japanese Hakone yosegi-zaiku secret boxes. Puzzle boxes are made to be solved once, by a stranger, and the makers tend to be people who enjoy being clever at something that has to work on a first encounter.",
    "start": "Look up a diagram of a six-piece burr puzzle and sketch the notch each stick needs so that only one removal order works."
