    "aka": "pcb design circuit design electronics art physical computing arduino soldering circuit art",
    "tag": "Circuits and boards made to be seen and used",
    "desc": "Designing circuits and boards for art, instruments and objects: schematics, PCB layout, sensors, LEDs and microcontrollers such as Arduino. Some makers treat the board itself as the artwork, with routed traces and silkscreen drawings, while others build interactive lights, synthesizers and installations. Small-run fabricators make the boards from files. Soldering by hand is a small, hot, irreversible commitment, and the people who take it up are usually the sort who would rather make it themselves than buy it.",
    "start": "Draw the circuit for a battery, a switch and an LED, and work out what each part does."
