    "tag": "Photographing what the eye cannot see",
    "desc": "Photographing what the eye cannot see unaided: night-sky objects through telescopes and long exposures, and tiny structures through microscopes (photomicrography). Astrophotographers stack many exposures to reveal faint detail and process the data, while microscopists use lighting and staining to show structure. The images serve as science records and as art. Astrophotography means long exposures in the dark and the cold, and attracts people willing to sit with nothing happening for hours.",
    "start": "Photograph the Moon with your phone braced against a wall or a stack of books, trying three exposure settings, and compare how much surface detail each one keeps."
