// ---------------------------------------------------------------------------
// Hierarchy: optional parentId on art forms.
//
// The catalogue keeps all 306 rows. Nothing is deleted or renamed, no id moves,
// and every row stays independently rateable, so saved sessions and existing
// ratings are untouched and the scoring engine is not fed a different question
// than before. What changes is that a row can now say what it is a kind of.
//
// SPLIT RUBRIC -- a row becomes a CHILD of a parent only when it shares the
// parent's core training and output, and differs mainly in which tradition,
// medium, subject or style it applies that training to:
//
//   child if   same practice, different instance   (Ballet is Dance; Fresco is Painting)
//   peer  if   the outcome changes                 (Editorial Cartooning argues a point;
//                                                    a Drawing does not)
//   peer  if   the tools change                    (Digital Painting is not brush Painting)
//   peer  if   the bodily or safety demands change (Pole Dance is not social dancing)
//   peer  if   the cultural protocol changes       (Mesoamerican Ritual Dance is not a
//                                                    genre you can learn from a class)
//
// A parent is not a duplicate of its children: "Dance" is moving to music without
// training in a named tradition, which is a real and common practice, and it is the
// right first row for someone who does not yet know whether they want ballet.
// A pure genre bucket with no unspecialised meaning of its own would instead be
// dropped, but the rule above deliberately never drops rows -- see
// holotype_audit/TAXONOMY_AUDIT.md for the parents still judged redundant.
//
// Multi-level is allowed and used once: Dance > Folk & Traditional > the regional
// traditions, so Folk & Traditional contains its children instead of competing
// beside them.
